UPDATE tools SET choose_if = $t2ci$["✅ אתם צריכים מצגות שמתעדכנות אוטומטית כשאתם מוסיפים תוכן", "✅ Smart Slides של Beautiful.ai מסתגלות לתוכן ושומרות על עיצוב אחיד", "✅ מתאים לצוותי שיווק שצריכים Brand consistency בכל מצגת", "✅ Beautiful.ai חזק יותר לעבודת צוות על מצגות רבות"]$t2ci$::JSONB, faq = $t2fq$[{"q": "Gamma לעומת Beautiful.ai – מה עדיף?", "a": "Gamma מהיר יותר ליצירת מצגת מהתחלה עם AI. Beautiful.ai טוב יותר לעקביות מותגית ולצוותים. Gamma למצגת מהירה; Beautiful.ai לצוותים עם Brand."}, {"q": "Beautiful.ai חינמי?", "a": "Beautiful.ai אין תוכנית חינמית קבועה; Pro ב-$12/חודש (שנתי). Gamma מציע תוכנית חינמית עם 400 נקודות AI; Plus ב-$10/חודש."}, {"q": "Gamma לעומת Canva – מה עדיף?", "a": "Gamma חזק יותר ב-AI generation ובמצגות web. Canva רחב יותר לכל סוגי הגרפיקה. Gamma למצגות מהירות; Canva לכל צרכי הוויזואל."}, {"q": "Beautiful.ai תומך בעברית?", "a": "Beautiful.ai תומך בטקסט עברי אך ה-AI generation באנגלית. ניתן להוסיף תוכן עברי ידנית לשקפים. RTL עשוי לדרוש התאמות ידניות."}]$t2fq$::JSONB WHERE slug = 'beautiful-ai' AND lang = 'he';
UPDATE tools SET choose_if = $t3ci$["✅ אתם רוצים לבנות SaaS מלא עם לוגיקה עסקית, מסד נתונים ומשתמשים", "✅ Bubble מאפשר בניית אפליקציות web מלאות ללא קוד – כולל backend", "✅ מתאים להקמת מוצרי MVP ו-SaaS עם הרשמות, תשלומים ואוטומציות", "✅ יש לו marketplace עם plugins לפונקציות מתקדמות"]$t3ci$::JSONB, faq = $t3fq$[{"q": "Bubble לעומת Webflow – מה לבחור?", "a": "Bubble לאפליקציות web עם לוגיקה ומסד נתונים. Webflow לאתרים ויזואליים ו-CMS. SaaS ו-Web App – Bubble; אתרי שיווק ועיצוב – Webflow."}, {"q": "Bubble חינמי?", "a": "Bubble מציע תוכנית חינמית; Starter ב-$32/חודש. Webflow Starter חינמי; Basic ב-$14/חודש."}, {"q": "Bubble לעומת Glide – מה ההבדל?", "a": "Bubble לאפליקציות web מורכבות. Glide לאפליקציות פשוטות ממקורות Google Sheets. Bubble עוצמתי יותר; Glide מהיר יותר להשקה."}, {"q": "Webflow SEO – כמה זה טוב?", "a": "Webflow מצוין ל-SEO – HTML נקי, meta tags, sitemap אוטומטי ו-301 redirects. אחד הפתרונות הטובים ביותר ל-SEO בין בוני האתרים ללא קוד."}]$t3fq$::JSONB WHERE slug = 'bubble' AND lang = 'he';
UPDATE tools SET choose_if = $t4ci$["✅ אתם רוצים לדעת מה הקונצנזוס המדעי על שאלה ספציפית", "✅ Consensus מציג אחוז הסכמה בין מחקרים על נושא מסוים", "✅ ממשק פשוט לאנשים שרוצים תשובה מהירה מהספרות המדעית", "✅ מתאים לאנשי מקצוע ועיתונאים שצריכים לאמת טענות מדעיות"]$t4ci$::JSONB, faq = $t4fq$[{"q": "Elicit לעומת Consensus – מה ההבדל?", "a": "Elicit מיועד לחקירה עמוקה ולניתוח כמויות גדולות של מאמרים. Consensus מיועד לשאלות מהירות על קונצנזוס מדעי. Elicit לחוקרים; Consensus לאישור טענות מדעיות."}, {"q": "האם Elicit חינמי?", "a": "Elicit מציע גישה חינמית מוגבלת. Plus ב-$12/חודש. Consensus מציע תוכנית חינמית; Premium ב-$9.99/חודש."}, {"q": "Elicit לעומת Google Scholar – מה עדיף?", "a": "Google Scholar הוא מנוע חיפוש למאמרים. Elicit ממיר את המחקרים לסיכומים ומחלץ נתונים. שניהם משלימים – חפשו ב-Scholar, נתחו ב-Elicit."}, {"q": "Consensus מדויק?", "a": "Consensus מציג נתונים מ-PubMed וממקורות אקדמיים אחרים. הוא שימושי כנקודת פתיחה אך לא תחליף לקריאת המאמרים המלאים. מומלץ לאמת ממצאים קריטיים ישירות."}]$t4fq$::JSONB WHERE slug = 'consensus' AND lang = 'he';
