UPDATE tools SET choose_if = $t26ci$["✅ אתם או ילדיכם מתקשים במתמטיקה וצריכים פתרונות שלב-אחר-שלב", "✅ Photomath מסביר כיצד לפתור בעיות מתמטיקה בצילום", "✅ מכסה אלגברה, טריגונומטריה, חשבון ועוד", "✅ חינמי לשימוש בסיסי – מושלם לשיעורי בית"]$t26ci$::JSONB, faq = $t26fq$[{"q": "Photomath לעומת Duolingo Max – מה ההבדל?", "a": "שניהם כלי חינוך AI אך לתחומים שונים. Photomath למתמטיקה; Duolingo Max ללימוד שפות. לפי צרכיכם."}, {"q": "Photomath חינמי?", "a": "Photomath חינמי לפתרונות בסיסיים; Photomath Plus ב-$9.99/חודש לפתרונות מפורטים. Duolingo Plus ב-$14.99/חודש; Duolingo Max ב-$29.99/חודש."}, {"q": "Duolingo Max שווה את המחיר?", "a": "Duolingo Max מוסיף Roleplay ו-Explain My Answer שהם שיפור ניכר ל-Plus. אם אתם משתמשים ב-Duolingo באופן יומיומי – כן, שווה. לשימוש מזדמן – Plus מספיק."}, {"q": "Photomath לבגרות מתמטיקה?", "a": "Photomath עוזר להבין פתרונות אך אינו תחליף לתרגול. לבגרות, מומלץ לפתור ולהשתמש ב-Photomath לבדיקה ולהבנת שלבים, לא להעתקה."}]$t26fq$::JSONB WHERE slug = 'photomath' AND lang = 'he';
UPDATE tools SET choose_if = $t27ci$["✅ אתם יוצרים Investor Decks ומצגות מכירה עם Analytics מתקדמות", "✅ Pitch מציג מי פתח את ה-Deck ואיך אותם צפו בכל שקף", "✅ templates מקצועיים לסטארטאפים ו-Business Pitches", "✅ שיתוף פעולה בצוות – Live Editing, הערות ו-Version History"]$t27ci$::JSONB, faq = $t27fq$[{"q": "Gamma לעומת Pitch – מה עדיף לסטארטאפ?", "a": "Pitch מועדף לסטארטאפים לגיוס כסף – Analytics ו-templates לסטארטאפ. Gamma מהיר יותר לפרוטוטייפ ולמצגות שיווקיות. Pitch לגיוס; Gamma לשיווק ולמצגות מהירות."}, {"q": "Pitch חינמי?", "a": "Pitch מציע תוכנית חינמית לעד 3 חברים; Pro ב-$8/חבר/חודש. Gamma חינמי עם 400 נקודות; Plus ב-$10/חודש."}, {"q": "Pitch Analytics – מה זה אומר?", "a": "Pitch מראה מי פתח את המצגת, כמה זמן הוקדש לכל שקף ואם שותפו קישורים. קריטי לסטארטאפים שרוצים לדעת האם VC צפה בכל ה-Deck."}, {"q": "Gamma לעומת Google Slides?", "a": "Gamma מהיר יותר ומייצר עיצוב אוטומטי. Google Slides מוכר לכולם, חינמי לחלוטין ועובד עם Google Workspace. Gamma לחוויה טובה יותר; Slides לתאימות וחינמיות."}]$t27fq$::JSONB WHERE slug = 'pitch' AND lang = 'he';
UPDATE tools SET choose_if = $t28ci$["✅ אתם צריכים AI שמוסיף אוטומטית זמן לעבודה ממוקדת ללוח שנה שלכם", "✅ Reclaim.ai שומר על הרגלים, זמן ארוחות ופגישות חוזרות בלוח ה-Calendar", "✅ אינטגרציה חלקה עם Google Calendar ללא מעבר לאפליקציה חדשה", "✅ מתאים לאנשים שרוצים הגנה על זמן אישי מבלי לשנות את מערכת הלו\"ז הקיימת"]$t28ci$::JSONB, faq = $t28fq$[{"q": "Motion לעומת Reclaim.ai – מה עדיף?", "a": "Motion הוא פתרון תזמון מלא שמחליף את כל ניהול הלו\"ז. Reclaim.ai מוסיף שכבת AI על Google Calendar הקיים. Motion לניהול עמוק; Reclaim לשיפור קל יותר."}, {"q": "כמה עולה Motion?", "a": "Motion עולה $34/חודש לאדם יחיד. Reclaim.ai מציע תוכנית חינמית; Starter ב-$10/חודש."}, {"q": "Reclaim.ai עובד עם Outlook?", "a": "Reclaim.ai תומך בעיקר ב-Google Calendar. תמיכה ב-Outlook מוגבלת. לשילוב עם Microsoft 365, Clockwise או Microsoft Copilot Calendar עשויים להתאים יותר."}, {"q": "Motion שווה את המחיר?", "a": "עבור אנשים שמרוויחים בשעה יותר מ-$34, Motion שווה את ההשקעה אם הוא אכן חוסך שעה לשבוע בתזמון. ניסיון חינמי זמין לפני ההחלטה."}]$t28fq$::JSONB WHERE slug = 'reclaim-ai' AND lang = 'he';
UPDATE tools SET choose_if = $t29ci$["✅ אתם צריכים לבנות כלים פנימיים מותאמים אישית עם AI מעל מסדי נתונים", "✅ Retool מאפשר בניית אפליקציות CRUD, דשבורדים ו-Workflows עם AI", "✅ מחבר ל-PostgreSQL, MongoDB, REST APIs ומסדי נתונים ארגוניים", "✅ מתאים לצוותי הנדסה שרוצים לבנות כלים פנימיים מהר ללא frontend מלא"]$t29ci$::JSONB, faq = $t29fq$[{"q": "Retool לעומת Looker Studio – מה ההבדל?", "a": "Retool לבניית כלים פנימיים ואפליקציות. Looker Studio לדשבורדי BI. Retool לצוותים טכניים שבונים כלים; Looker לצוותי עסקים שצופים בנתונים."}, {"q": "כמה עולה Retool?", "a": "Retool מציע תוכנית חינמית ל-5 משתמשים; Team ב-$10/משתמש/חודש. Looker Studio חינמי לחלוטין."}, {"q": "Retool AI – מה הכוונה?", "a": "Retool AI הוא שכבת AI ב-Retool שמאפשרת חיפוש בשפה טבעית, גנרציית SQL ומינוי מודלי AI (GPT-4, Claude) בתוך הכלים הפנימיים שבניתם."}, {"q": "Retool לעומת Bubble?", "a": "Retool מתאים לכלים פנימיים ולנתונים מסד. Bubble מתאים לאפליקציות ציבוריות עם משתמשי קצה. Retool לops tools; Bubble ל-SaaS ולאפליקציות לקוחות."}]$t29fq$::JSONB WHERE slug = 'retool-ai' AND lang = 'he';
UPDATE tools SET choose_if = $t30ci$["✅ אתם צריכים גיליון אלקטרוני חכם עם אינטגרציות API ו-AI מובנה", "✅ Rows מחבר ל-APIs, מסדי נתונים ואוטומציות בממשק של טבלת Excel", "✅ AI Analyst מנתח נתונים ויוצר גרפים מתיאור בשפה טבעית", "✅ מתאים לאנליסטים ואנשי עסקים שרוצים עוצמת גיליון אלקטרוני מחוזקת ב-AI"]$t30ci$::JSONB, faq = $t30fq$[{"q": "Rows לעומת Hex – מה ההבדל?", "a": "Rows הוא גיליון אלקטרוני חכם עם AI ו-APIs. Hex הוא Notebook שיתופי לצוותי Data Science. Rows לאנשי עסקים; Hex לאנשי נתונים טכניים."}, {"q": "Rows חינמי?", "a": "Rows מציע תוכנית חינמית; Plus ב-$59/חודש לצוות. Hex מציע תוכנית חינמית; Team ב-$24/משתמש/חודש."}, {"q": "Rows לעומת Excel – מה עדיף?", "a": "Rows מציע אינטגרציות API ו-AI שאין ב-Excel. Excel מציע תאימות אוניברסלית ויכולות מתקדמות. Rows לנתונים מהאינטרנט ו-APIs; Excel לעבודה קלאסית עם גיליונות."}, {"q": "Rows לחיבור ל-Airtable?", "a": "Rows מתחבר ל-Airtable דרך API. ניתן לייבא נתוני Airtable, לנתח ולהציג אותם בממשק Rows."}]$t30fq$::JSONB WHERE slug = 'rows' AND lang = 'he';
UPDATE tools SET choose_if = $t31ci$["✅ אתם רוצים לדעת האם מאמר מדעי קיבל ציטוטים תומכים, סותרים או ניטרליים", "✅ Scite מציג Smart Citations – הקשר הציטוט, לא רק מספרו", "✅ מתאים לחוקרים שרוצים להעריך את אמינות ואיכות ממצאי מחקר", "✅ כלי ייחודי לבדיקת רובסטיות של עבודות מדעיות"]$t31ci$::JSONB, faq = $t31fq$[{"q": "Scite לעומת Semantic Scholar – מה ההבדל?", "a": "Scite מתמחה בניתוח ציטוטים לפי הקשר – תומך, סותר או ניטרלי. Semantic Scholar הוא מנוע חיפוש אקדמי כללי עם AI. Scite לאימות מחקר; Semantic Scholar לחיפוש ספרות."}, {"q": "Scite חינמי?", "a": "Scite מציע חיפוש בסיסי חינמי; Individual ב-$20/חודש לגישה מלאה. Semantic Scholar חינמי לחלוטין."}, {"q": "Semantic Scholar לעומת Google Scholar?", "a": "שניהם חינמיים ומאנדקסים מאמרים אקדמיים. Semantic Scholar מציע AI כמו TLDR ו-Paper Recommendations. Google Scholar מכסה יותר מקורות ויש לו אינדקס גדול יותר."}, {"q": "Scite לרפואה מבוססת ראיות?", "a": "כן, Scite מצוין ל-Evidence-based Medicine. Smart Citations מאפשרות לראות האם מחקרים אחרים תמכו או הפריכו ממצא קליני ספציפי."}]$t31fq$::JSONB WHERE slug = 'scite' AND lang = 'he';
UPDATE tools SET choose_if = $t32ci$["✅ אתם צריכים מנוע חיפוש אקדמי חינמי ועוצמתי עם AI", "✅ Semantic Scholar מאנדקס מאות מיליוני מאמרים ממדעים שונים", "✅ TLDR AI מייצר תקציר בן משפט אחד לכל מאמר", "✅ חינמי לחלוטין – ללא הגבלה לחיפוש ולצפייה בנתוני ציטוטים"]$t32ci$::JSONB, faq = $t32fq$[{"q": "Scite לעומת Semantic Scholar – מה ההבדל?", "a": "Scite מתמחה בניתוח ציטוטים לפי הקשר – תומך, סותר או ניטרלי. Semantic Scholar הוא מנוע חיפוש אקדמי כללי עם AI. Scite לאימות מחקר; Semantic Scholar לחיפוש ספרות."}, {"q": "Scite חינמי?", "a": "Scite מציע חיפוש בסיסי חינמי; Individual ב-$20/חודש לגישה מלאה. Semantic Scholar חינמי לחלוטין."}, {"q": "Semantic Scholar לעומת Google Scholar?", "a": "שניהם חינמיים ומאנדקסים מאמרים אקדמיים. Semantic Scholar מציע AI כמו TLDR ו-Paper Recommendations. Google Scholar מכסה יותר מקורות ויש לו אינדקס גדול יותר."}, {"q": "Scite לרפואה מבוססת ראיות?", "a": "כן, Scite מצוין ל-Evidence-based Medicine. Smart Citations מאפשרות לראות האם מחקרים אחרים תמכו או הפריכו ממצא קליני ספציפי."}]$t32fq$::JSONB WHERE slug = 'semantic-scholar' AND lang = 'he';
UPDATE tools SET choose_if = $t33ci$["✅ אתם רוצים לבנות client portal, internal tool או membership site מ-Airtable", "✅ Softr מהיר וקל לשימוש – אתר ראשון תוך שעה ממקור Airtable", "✅ templates מוכנים לפורטלי לקוחות, Job boards ו-Directories", "✅ מחיר נוח יותר מ-Bubble עם פחות עקומת למידה"]$t33ci$::JSONB, faq = $t33fq$[{"q": "Softr לעומת Bubble – מה עדיף?", "a": "Softr מהיר יותר לפרוטלי לקוחות ו-membership sites מ-Airtable. Bubble עוצמתי יותר לאפליקציות מורכבות. לפורטלים ו-directories – Softr; ל-SaaS – Bubble."}, {"q": "Softr חינמי?", "a": "Softr מציע תוכנית חינמית עם 100 משתמשי app; Basic ב-$49/חודש. Bubble מציע תוכנית חינמית; Starter ב-$32/חודש."}, {"q": "Softr לעומת Glide?", "a": "שניהם בונים אפליקציות מ-Airtable. Softr ממוקד יותר ב-portals ו-directories עם חברות. Glide מתאים יותר לאפליקציות פנים-ארגוניות. Softr לחיצונים; Glide לפנימיים."}, {"q": "Softr מתאים ל-Job Board?", "a": "כן, Softr הוא אחד הפתרונות הנוחים ביותר לבניית Job Board ב-no-code. Template מוכן זמין; ניתן להקים Job Board תוך שעות בחיבור ל-Airtable."}]$t33fq$::JSONB WHERE slug = 'softr' AND lang = 'he';
UPDATE tools SET choose_if = $t34ci$["✅ אתם רוצים ליצור שירים מלאים עם מוזיקה, מנגינה ומילים מפרומפט טקסטואלי", "✅ Suno יוצר מוזיקה מקורית בכל סגנון – פופ, רוק, ג'אז, היפ-הופ ועוד", "✅ מאפשר יצירת תוכן מוזיקלי ייחודי ללא ידע מוזיקלי קודם", "✅ מתאים לסרטונים, פרויקטים יצירתיים ומוזיקה לרקע"]$t34ci$::JSONB, faq = $t34fq$[{"q": "Suno לעומת ElevenLabs – מה ההבדל?", "a": "Suno יוצר מוזיקה שלמה עם מנגינה ומילים. ElevenLabs ממיר טקסט לדיבור בקולות AI. שניהם שונים לחלוטין – Suno למוזיקה, ElevenLabs לנרטיב ודיבור."}, {"q": "האם Suno חינמי?", "a": "Suno מציע תוכנית חינמית עם 50 שירים ליום. Pro ב-$10/חודש. ElevenLabs חינמי עם 10,000 תווים לחודש; Starter ב-$5/חודש."}, {"q": "האם ElevenLabs תומך בעברית?", "a": "כן, ElevenLabs תומך בעברית עם איכות גבוהה. ניתן ליצור שכפול קולי בעברית ולהמיר טקסט עברי לדיבור טבעי."}, {"q": "האם ניתן להשתמש במוזיקה מ-Suno מסחרית?", "a": "בתוכנית Pro ו-Premier של Suno ניתן להשתמש ביצירות מסחרית. בתוכנית החינמית הזכויות מוגבלות. חשוב לקרוא את תנאי השימוש לפני פרסום מסחרי."}]$t34fq$::JSONB WHERE slug = 'suno' AND lang = 'he';
UPDATE tools SET choose_if = $t35ci$["✅ אתם הורים לילדים 5-14 שרוצים פלטפורמת למידה מבוססת משחקים וחשיבה", "✅ Synthesis פיתחה על ידי SpaceX ומתמקדת בחשיבה ביקורתית ופתרון בעיות", "✅ למידה חברתית – ילדים עובדים יחד עם ילדים אחרים באתגרים", "✅ מתאים להאצת ילדים מחוננים שצריכים גירוי מעבר לתכנית הלימודים"]$t35ci$::JSONB, faq = $t35fq$[{"q": "Synthesis לעומת Khanmigo – מה ההבדל?", "a": "Synthesis ממוקד בחשיבה ביקורתית ובפתרון בעיות דרך משחקים. Khanmigo מורה AI לעזרה בחומר לימודי. Synthesis להאצה וגמישות; Khanmigo לתמיכה בחומר בית-ספרי."}, {"q": "Synthesis כמה עולה?", "a": "Synthesis עולה $35/חודש לילד. Khanmigo ב-$9/חודש; ממתן חינמי בחלק מהמדינות."}, {"q": "Synthesis – מה הקשר ל-SpaceX?", "a": "Synthesis פותחה במקור לילדי עובדי SpaceX. הפכה לחברה עצמאית ב-2022 ופתחה לציבור. מייסדיה הגיעו מסביבת חינוך SpaceX."}, {"q": "Synthesis מתאים לגיל כמה?", "a": "Synthesis מיועד לגילאי 5-14. יש תכניות שונות לפי גיל. הפלטפורמה מתאימה במיוחד לשלב גן-חטיבה עם דגש על חשיבה לוגית ומתמטיקה."}]$t35fq$::JSONB WHERE slug = 'synthesis' AND lang = 'he';
UPDATE tools SET choose_if = $t36ci$["✅ אתם צריכים פלטפורמת BI מתקדמת עם AI לניתוח עמוק של נתונים מורכבים", "✅ Tableau AI (Einstein) מייצר תובנות, חיזויים ואנומליות אוטומטית", "✅ הפלטפורמה המקצועית הסטנדרטית לאנליסטים ואנשי Data ב-Enterprise", "✅ יכולות ויזואליזציה מתקדמות שאין ב-Looker Studio"]$t36ci$::JSONB, faq = $t36fq$[{"q": "Looker Studio לעומת Tableau – מה עדיף?", "a": "Looker Studio חינמי ומצוין לאינטגרציה עם Google. Tableau מקצועי יותר ועוצמתי לנתונים מורכבים. לעסקים קטנים וסטארטאפים – Looker Studio; לEnterprise – Tableau."}, {"q": "Looker Studio חינמי לחלוטין?", "a": "כן, Looker Studio חינמי לחלוטין לשימוש בסיסי. Tableau Creator ב-$75/משתמש/חודש; Viewer ב-$15/חודש."}, {"q": "מה ההבדל בין Looker ו-Looker Studio?", "a": "Looker Studio (לשעבר Data Studio) הוא כלי BI חינמי ל-דשבורדים. Looker (נרכש ע\"י Google) הוא פלטפורמת BI מלאה Enterprise בתשלום. שני מוצרים שונים תחת מותג Google."}, {"q": "Tableau AI – מה הכוונה?", "a": "Tableau AI (Einstein Copilot) הוא שכבת AI ש-Salesforce מוסיפה ל-Tableau. מאפשר שאילת שאלות בשפה טבעית, זיהוי חריגות ויצירת תובנות אוטומטית."}]$t36fq$::JSONB WHERE slug = 'tableau-ai' AND lang = 'he';
UPDATE tools SET choose_if = $t37ci$["✅ אתם צריכים לבנות אתר marketing או CMS מרהיב ללא קוד", "✅ Webflow מציע עיצוב ויזואלי מקצועי עם CMS ו-SEO מצוין", "✅ לאנשי עיצוב שרוצים שליטה מלאה בעיצוב ללא פשרות", "✅ מתאים לאתרי שיווק, לאתרי פורטפוליו ולסוכנויות"]$t37ci$::JSONB, faq = $t37fq$[{"q": "Bubble לעומת Webflow – מה לבחור?", "a": "Bubble לאפליקציות web עם לוגיקה ומסד נתונים. Webflow לאתרים ויזואליים ו-CMS. SaaS ו-Web App – Bubble; אתרי שיווק ועיצוב – Webflow."}, {"q": "Bubble חינמי?", "a": "Bubble מציע תוכנית חינמית; Starter ב-$32/חודש. Webflow Starter חינמי; Basic ב-$14/חודש."}, {"q": "Bubble לעומת Glide – מה ההבדל?", "a": "Bubble לאפליקציות web מורכבות. Glide לאפליקציות פשוטות ממקורות Google Sheets. Bubble עוצמתי יותר; Glide מהיר יותר להשקה."}, {"q": "Webflow SEO – כמה זה טוב?", "a": "Webflow מצוין ל-SEO – HTML נקי, meta tags, sitemap אוטומטי ו-301 redirects. אחד הפתרונות הטובים ביותר ל-SEO בין בוני האתרים ללא קוד."}]$t37fq$::JSONB WHERE slug = 'webflow' AND lang = 'he';
UPDATE tools SET choose_if = $t38ci$["✅ אתם רוצים ללמוד מסרטוני YouTube, PDF ומאמרים עם AI שמסכם ומסביר", "✅ YouLearn מייצר flashcards ושאלות חידון מהחומר שהעלאתם", "✅ מעקב התקדמות ולמידה אדפטיבית לפי הידע שלכם", "✅ מתאים לסטודנטים שרוצים לשנן ולהבין חומר לבחינות"]$t38ci$::JSONB, faq = $t38fq$[{"q": "YouLearn לעומת NotebookLM – מה עדיף?", "a": "YouLearn ממוקד בלמידה אקטיבית עם flashcards ושאלות. NotebookLM ממוקד בניתוח ושיחה עם מסמכים. YouLearn לשינון; NotebookLM לחקירה."}, {"q": "YouLearn חינמי?", "a": "YouLearn מציע תוכנית חינמית עם הגבלות; Pro ב-$10/חודש. NotebookLM חינמי לחלוטין."}, {"q": "YouLearn לעומת Anki?", "a": "Anki כלי flashcard קלאסי עם spaced repetition. YouLearn מייצר flashcards אוטומטית מהחומר שלכם עם AI. YouLearn מהיר יותר להכנת חומר; Anki טוב יותר לשינון לטווח ארוך."}, {"q": "NotebookLM Audio Overview – איך זה עובד?", "a": "NotebookLM יוצר פודקאסט שיחה בין שני קולות AI שמדונים בתוכן מסמכיכם. מייצר בדקות ויכול לעזור להבין חומר מורכב בדרך מעניינת."}]$t38fq$::JSONB WHERE slug = 'youlearn' AND lang = 'he';
UPDATE tools SET choose_if = $t39ci$["✅ אתם רוצים אוטומציות חכמות בין אפליקציות עם AI שמקבל החלטות", "✅ Zapier AI מחבר אלפי אפליקציות ומוסיף לוגיקת AI לתהליכי עבודה אוטומטיים", "✅ יצירת Chatbots ו-Agents שפועלים ומבצעים משימות ללא התערבות ידנית", "✅ מתאים לצוותים שרוצים לחסוך זמן על ידי אוטומציה עם AI ולא רק עריכת תוכן"]$t39ci$::JSONB, faq = $t39fq$[{"q": "Notion AI לעומת Zapier AI – מה ההבדל?", "a": "Notion AI הוא עוזר כתיבה ועריכה בתוך Notion. Zapier AI הוא פלטפורמת אוטומציה שמוסיפה AI לזרימות עבודה בין אפליקציות. Notion למסמכים וידע; Zapier לאוטומציה."}, {"q": "כמה עולה Notion AI?", "a": "Notion AI עולה $10/משתמש/חודש בנוסף לתוכנית Notion הבסיסית. Zapier מציע תוכנית חינמית; תוכניות בתשלום מ-$19.99/חודש."}, {"q": "האם Notion AI יכול לחפש באינטרנט?", "a": "Notion AI יכול לחפש מידע באינטרנט בגרסאות מסוימות, אך בעיקרו הוא עובד עם תוכן Notion הקיים. לחיפוש אינטרנטי מתקדם, Perplexity AI או ChatGPT Plus עדיפים."}, {"q": "Zapier AI – האם זה שימושי לעסקים קטנים?", "a": "כן. Zapier AI מאפשר לעסקים קטנים לאוטומט תהליכים שדרשו כוח אדם. מאיל עד CRM ועד ניהול לידים – Zapier חוסך שעות עבודה שבועיות."}]$t39fq$::JSONB WHERE slug = 'zapier-ai' AND lang = 'he';
COMMIT;